import type { ComponentProps, ForwardRefExoticComponent, JSX } from "react";

type MotionProps<Tag extends keyof JSX.IntrinsicElements> = ComponentProps<Tag> & {
  animate?: Record<string, unknown>;
  initial?: Record<string, unknown>;
  exit?: Record<string, unknown>;
  variants?: Record<string, unknown>;
  transition?: Record<string, unknown>;
  layout?: boolean;
  layoutId?: string;
  drag?: boolean | "x" | "y";
  whileHover?: Record<string, unknown>;
  whileTap?: Record<string, unknown>;
  whileInView?: Record<string, unknown>;
  onTap?: () => void;
};

export declare const motion: {
  [Tag in keyof JSX.IntrinsicElements]: ForwardRefExoticComponent<MotionProps<Tag>>;
};
